action.transformation:
$showFormDialog(
    {
      'title': '',
      'formInputs': [
    {
    "label": "Work Order Number",
    "validation": {
      "required": true
    },
    "dataPath": "workOrderNumber",
    "field": "workOrderNumber",
    "description": "job number",
    "element": "TextInput",
    "type": "text"
  },
    {
      "label": "Required Quantity",
      "validation": {
        "required": true
      },
      "dataPath": "requiredQuantity",
      "field": "requiredQuantity",
      "description": "What's the required quantity (total) for the run",
      "element": "FloatInput",
      "type": "float"
    }, 

    {
      "label": "Workcenter",
      "validation": {
        "required": true
      },
      "dataPath": "workcenter",
      "field": "workcenter",
      "description": "Workcenter object",
      "element": "Combobox",
      "type": "combobox",
      "api": "Application",
      "queryType": "Workcenter",
      "labelField": "code",
      "labelPath": "code",
      "additionalFields": "code facilityId",
      "target": {
        "dataPath": "workcenterId"
      },
      "query": {
        "fields": [
          "workcenter.id",
          "workcenter.code"
        ]
      }
    },

    {
      "label": "Part No Revision",
      "validation": {
        "required": true
      },
      "dataPath": "productNoRevision",
      "field": "productNoRevision",
      "description": "productNoRevision",
      "element": "Combobox",
      "type": "combobox",
      "api": "Application",
      "queryType": "ApprovedWorkcenter",
      "labelField": "productNoRevision",
      "labelPath": "productNoRevision",
      "target": {
        "dataPath": "productNoRevision"
      },
      "disabled":{
        "__transform": "$isNilOrEmpty(data.workcenter)"
      },
      "additionalFilter":{
        "__transform": "{ 'workcenterId': { '_eq': data.workcenter.id} }"
      }
    },

    {
      "label": "Operation",
      "validation": {
        "required": true
      },
      "dataPath": "operationCode",
      "field": "operation",
      "description": "operation",
      "element": "Combobox",
      "type": "combobox",
      "api": "Application",
      "queryType": "ApprovedWorkcenter",
      "labelField": "operationCode",
      "labelPath": "operationCode",
      "target": {
        "dataPath": "operation"
      },
      "disabled":{
        "__transform": "$isNilOrEmpty(data.productNoRevision)"
      },
      "additionalFilter":{
        "__transform": "{ 'workcenterId': { '_eq': data.workcenter.id}, 'productNoRevision': { '_eq': data.productNoRevision.productNoRevision} }"
      },
      "additionalFields": "code unitsPerCycle crewSize idealRate setupCrewSize setupTime standardProductionRate standardQuantity targetRate active note operationCode operationNo productId productNo productNoRevision productOperationId productRevision workcenterId standardQuantity"
    }

  ], 
      'submitIcon': 'right-long'
    }
  )

transforms.pre:
(
  $create := {
    "number": data.form1.number,
    "requiredQuantity": data.form1.requiredQuantity,
    "balanceQuantity": data.form1.requiredQuantity,
    "idealRate": data.form1.operationCode.idealRate,
    "setupOperators": data.form1.operationCode.setupCrewSize,
    "standardRate": data.form1.operationCode.standardProductionRate,
    "operationCode": data.form1.operationCode.operationCode,
    "operationNumber": data.form1.operationCode.operationNo,
    "productId": data.form1.operationCode.productId,
    "productNumber": data.form1.operationCode.productNo,
    "productNumberRevision": data.form1.operationCode.productNoRevision,
    "productRevision": data.form1.operationCode.productRevision,
    "facilityId": data.form1.workcenter.facilityId,
    "workcenterId": data.form1.workcenter.id,
    "standardQuantity": data.form1.operationCode.standardQuantity,
    "workOrderNumber": data.form1.workOrderNumber
  };

  {
    "payload": {
      "create": $merge([$create, data.form2, data.form3]) 
    }
  };

)
